macro_rules! deps {
    () => {
        Renderer!();
        SubstitutionHighlight!();
        DisplaySuggestion!();
        LineInfo!();
        StyledBuffer!();
        ElementStyle!();
    };
}

macro_rules! draw_code_line {
    () => {
        deps!();
        # [allow (clippy :: too_many_arguments)] fn draw_code_line (renderer : & Renderer , buffer : & mut StyledBuffer , row_num : & mut usize , highlight_parts : & [SubstitutionHighlight] , line_num : usize , line_to_add : & str , show_code_change : DisplaySuggestion , max_line_num_len : usize , file_lines : & [& LineInfo < '_ >] , is_multiline : bool ,) { if let DisplaySuggestion :: Diff = show_code_change { let lines_to_remove = file_lines . iter () . take (file_lines . len () - 1) ; for (index , line_to_remove) in lines_to_remove . enumerate () { buffer . puts (* row_num - 1 , 0 , & maybe_anonymized (renderer , line_num + index , max_line_num_len) , ElementStyle :: LineNumber ,) ; buffer . puts (* row_num - 1 , max_line_num_len + 1 , "- " , ElementStyle :: Removal ,) ; let line = normalize_whitespace (line_to_remove . line) ; buffer . puts (* row_num - 1 , max_line_num_len + 3 , & line , ElementStyle :: NoStyle ,) ; * row_num += 1 ; } let last_line = & file_lines . last () . unwrap () ; if last_line . line == line_to_add { * row_num -= 2 ; } else { buffer . puts (* row_num - 1 , 0 , & maybe_anonymized (renderer , line_num + file_lines . len () - 1 , max_line_num_len) , ElementStyle :: LineNumber ,) ; buffer . puts (* row_num - 1 , max_line_num_len + 1 , "- " , ElementStyle :: Removal ,) ; buffer . puts (* row_num - 1 , max_line_num_len + 3 , & normalize_whitespace (last_line . line) , ElementStyle :: NoStyle ,) ; if line_to_add . trim () . is_empty () { * row_num -= 1 ; } else { buffer . puts (* row_num , 0 , & maybe_anonymized (renderer , line_num , max_line_num_len) , ElementStyle :: LineNumber ,) ; buffer . puts (* row_num , max_line_num_len + 1 , "+ " , ElementStyle :: Addition) ; buffer . append (* row_num , & normalize_whitespace (line_to_add) , ElementStyle :: NoStyle ,) ; } } } else if is_multiline { buffer . puts (* row_num , 0 , & maybe_anonymized (renderer , line_num , max_line_num_len) , ElementStyle :: LineNumber ,) ; match & highlight_parts { [SubstitutionHighlight { start : 0 , end }] if * end == line_to_add . len () => { buffer . puts (* row_num , max_line_num_len + 1 , "+ " , ElementStyle :: Addition) ; } [] | [SubstitutionHighlight { start : 0 , end : 0 }] => { draw_col_separator_no_space (renderer , buffer , * row_num , max_line_num_len + 1) ; } _ => { let diff = renderer . decor_style . diff () ; buffer . puts (* row_num , max_line_num_len + 1 , & format ! ("{diff} ") , ElementStyle :: Addition ,) ; } } buffer . puts (* row_num , max_line_num_len + 3 , & normalize_whitespace (line_to_add) , ElementStyle :: NoStyle ,) ; } else if let DisplaySuggestion :: Add = show_code_change { buffer . puts (* row_num , 0 , & maybe_anonymized (renderer , line_num , max_line_num_len) , ElementStyle :: LineNumber ,) ; buffer . puts (* row_num , max_line_num_len + 1 , "+ " , ElementStyle :: Addition) ; buffer . append (* row_num , & normalize_whitespace (line_to_add) , ElementStyle :: NoStyle ,) ; } else { buffer . puts (* row_num , 0 , & maybe_anonymized (renderer , line_num , max_line_num_len) , ElementStyle :: LineNumber ,) ; draw_col_separator (renderer , buffer , * row_num , max_line_num_len + 1) ; buffer . append (* row_num , & normalize_whitespace (line_to_add) , ElementStyle :: NoStyle ,) ; } for & SubstitutionHighlight { start , end } in highlight_parts { if start != end { let tabs : usize = line_to_add . chars () . take (start) . map (| ch | match ch { '\t' => 3 , _ => 0 , }) . sum () ; buffer . set_style_range (* row_num , max_line_num_len + 3 + start + tabs , max_line_num_len + 3 + end + tabs , ElementStyle :: Addition , true ,) ; } } * row_num += 1 ; }
    };
}

draw_code_line!();